package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
	"github.com/luwa07832/rbac-admin-api/internal/store"
)

// NewRouter wires the public HTTP surface. The service contract in README.md
// describes the error shape every entry must keep.
func NewRouter(st *store.Store) *gin.Engine {
	gin.SetMode(gin.ReleaseMode)
	router := gin.New()
	// Identifiers may contain "/" (e.g. "tenant-a/doc-1"); keep %2F encoded
	// inside a single path parameter instead of splitting the route.
	router.UseRawPath = true
	router.UnescapePathValues = false
	router.Use(gin.Recovery())

	service := authz.NewService(st)

	router.GET("/healthz", func(c *gin.Context) {
		if err := st.Ping(); err != nil {
			c.JSON(http.StatusServiceUnavailable, gin.H{"error": gin.H{"code": "storage_unavailable", "message": "database is not available"}})
			return
		}
		c.JSON(http.StatusOK, gin.H{"status": "ok", "database": "ok"})
	})

	registerCatalog(router, service, "subjects", store.CatalogSubject)
	registerCatalog(router, service, "resources", store.CatalogResource)
	registerCatalog(router, service, "operations", store.CatalogOperation)
	registerCatalog(router, service, "roles", store.CatalogRole)
	registerCatalog(router, service, "permissions", store.CatalogPermission)

	router.PUT("/roles/:id/parents", setRoleParentsHandler(service))
	router.PUT("/permissions/:id/operations", setPermissionOperationsHandler(service))

	router.PUT("/subjects/:id/bindings/:role", grantBindingHandler(service))
	router.PATCH("/subjects/:id/bindings/:role", updateBindingHandler(service))
	router.DELETE("/subjects/:id/bindings/:role", revokeBindingHandler(service))

	router.PUT("/roles/:id/permissions/:perm", grantRolePermissionHandler(service))
	router.PATCH("/roles/:id/permissions/:perm", updateRolePermissionHandler(service))
	router.DELETE("/roles/:id/permissions/:perm", revokeRolePermissionHandler(service))

	router.PUT("/subjects/:id/scopes", grantScopeHandler(service))
	router.PATCH("/subjects/:id/scopes", updateScopeHandler(service))
	router.DELETE("/subjects/:id/scopes", revokeScopeHandler(service))

	router.POST("/authorize", authorizeHandler(service))
	router.GET("/history", historyHandler(service))
	router.GET("/subjects/:id/access", accessHandler(service))
	router.GET("/roles/:role/permissions", rolePermissionsHandler(service))
	router.GET("/resources/:resource/subjects", resourceSubjectsHandler(service))

	router.NoRoute(func(c *gin.Context) {
		c.JSON(http.StatusNotFound, gin.H{"error": gin.H{"code": "route_not_found", "message": "no route matches this path"}})
	})
	return router
}

func registerCatalog(router *gin.Engine, service *authz.Service, segment string, kind store.CatalogKind) {
	router.PUT("/"+segment+"/:id", func(c *gin.Context) {
		if fail := service.Register(authz.RegisterInput{Kind: kind, ID: pathParam(c, "id")}); fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"registered": true})
	})
}
package api

import (
	"net/http"

	"github.com/gin-gonic/gin"

	"github.com/luwa07832/rbac-admin-api/internal/authz"
)

type authorizeRequestBody struct {
	Subject     string `json:"subject"`
	Resource    string `json:"resource"`
	Operation   string `json:"operation"`
	EffectiveAt string `json:"effectiveAt"`
}

func authorizeHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		var body authorizeRequestBody
		if fail := readJSON(c, &body, false); fail != nil {
			writeFailure(c, fail)
			return
		}
		decision, fail := service.Decide(authz.DecisionInput{
			Subject:     body.Subject,
			Resource:    body.Resource,
			Operation:   body.Operation,
			EffectiveAt: body.EffectiveAt,
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"decision": decisionResponse(decision)})
	}
}

func decisionResponse(decision *authz.Decision) gin.H {
	if decision.Granted {
		return gin.H{
			"granted":           true,
			"matchedRole":       nullableJSON(decision.Match.Role),
			"matchedPermission": nullableJSON(decision.Match.Permission),
			"matchedScope":      decision.Match.Scope,
		}
	}
	return gin.H{"granted": false, "reason": decision.Reason}
}

func nullableJSON(value string) any {
	if value == "" {
		return nil
	}
	return value
}

func accessHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		items, fail := service.Access(authz.AccessInput{
			Subject:     pathParam(c, "id"),
			EffectiveAt: c.Query("effectiveAt"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"access": items})
	}
}

func rolePermissionsHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		view, fail := service.RolePermissions(authz.RolePermissionsInput{
			Role:        pathParam(c, "role"),
			EffectiveAt: c.Query("effectiveAt"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

func resourceSubjectsHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		view, fail := service.ResourceSubjects(authz.ResourceSubjectsInput{
			Resource:    pathParam(c, "resource"),
			Operation:   c.Query("operation"),
			EffectiveAt: c.Query("effectiveAt"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, view)
	}
}

func historyHandler(service *authz.Service) gin.HandlerFunc {
	return func(c *gin.Context) {
		subject := c.Query("subject")
		resource := c.Query("resource")
		operation := c.Query("operation")
		if subject == "" || resource == "" || operation == "" {
			writeFailure(c, &authz.Failure{
				Type:    authz.TypeInvalidRequest,
				Field:   "subject",
				Message: "subject, resource and operation query parameters are required",
			})
			return
		}
		events, fail := service.History(authz.HistoryInput{
			Subject:   subject,
			Resource:  resource,
			Operation: operation,
			From:      c.Query("from"),
			To:        c.Query("to"),
		})
		if fail != nil {
			writeFailure(c, fail)
			return
		}
		c.JSON(http.StatusOK, gin.H{"events": events})
	}
}

